function options(select,items,placeholder){const old=select.value;select.innerHTML=(placeholder!==undefined?`<option value="">${esc(placeholder)}</option>`:'')+items.map(x=>{const value=typeof x==='string'?x:x.value,text=typeof x==='string'?label(x):x.label;return `<option value="${esc(value)}">${esc(text)}</option>`}).join('');if([...select.options].some(o=>o.value===old))select.value=old}
