function getConfig(){return {baseSQL,selected:[...selected],quick:{from:$('dateFrom').value,to:$('dateTo').value,category:$('category').value,md:$('md').value,supplier:$('supplier').value,search:$('search').value.trim()},filters:filters.map(f=>({...f})),logic:$('logic').value,groups:$('groupMode').value==='detail'?[]:[...new Set(['group1','group2','group3'].map(id=>$(id).value).filter(Boolean))],metric:{operation:$('aggregate').value,column:$('metric').value},sort:$('sort').value,direction:$('direction').value}}
