function changeSource({presetId,source,run=true}={}){try{const preset=Q.presets.find(p=>p.id===presetId);if(preset){baseSQL=preset.sql;currentSource=preset.sql.match(/FROM\s+([^\s]+)/i)[1];$('preset').value=preset.id;$('queryDescription').textContent=preset.description;$('source').value=currentSource}else{currentSource=source||$('source').value;if(!objects.some(o=>o.name===currentSource))throw Error('DB에 없는 테이블입니다.');baseSQL='SELECT * FROM '+Q.quote(currentSource);$('preset').value='custom';$('source').value=currentSource;$('queryDescription').textContent='원본/뷰를 직접 선택했습니다. 필요한 칼럼과 필터를 구성하세요.'}
 columns=metaFor(baseSQL,currentSource);selected=defaultSelected();filters=[];$('filterRows').innerHTML='';$('columnCount').textContent=selected.length;$('sourceColumns').textContent=columns.length+'개 칼럼';$('category').value=$('md').value=$('supplier').value=$('search').value='';$('logic').value='AND';$('groupMode').value='detail';$('groupFields').hidden=true;$('aggregate').value='sum';for(const id of ['group1','group2','group3'])$(id).innerHTML=columnOptions(columns,true);$('metric').innerHTML='';metricOptions();const field=Q.findRole(columns,'date');dates={min:'',max:''};if(field){const r=execute('SELECT MIN(substr('+Q.quote(field)+',1,10)) AS lo, MAX(substr('+Q.quote(field)+',1,10)) AS hi FROM ('+baseSQL+')').rows[0];dates={min:r?.lo||'',max:r?.hi||''}}$('period').value=['daily','supplier','runs'].includes(presetId)?'all':'latest';setPeriod();quickOptions();updateSort();previewSQL();if(run)runQuery(false)}catch(e){showError(e)}}
function renderFilters(){const usable=columns.filter(c=>c.type!=='BLOB');$('filterRows').innerHTML=filters.map((f,index)=>{let values=[];try{values=execute('SELECT DISTINCT '+Q.quote(f.column)+' AS v FROM ('+baseSQL+') WHERE '+Q.quote(f.column)+' IS NOT NULL LIMIT 150').rows.map(r=>r.v)}catch(e){}return `<div class="filterrow"><div class="fhead"><select data-index="${index}" data-part="column" aria-label="필터 ${index+1} 칼럼">${usable.map(c=>`<option value="${esc(c.name)}" ${c.name===f.column?'selected':''}>${esc(label(c.name))}</option>`).join('')}</select><button class="remove" data-remove="${index}" aria-label="조건 ${index+1} 삭제">✕</button></div><div class="fvalue"><select data-index="${index}" data-part="operator" aria-label="필터 ${index+1} 비교">${operators.map(([v,l])=>`<option value="${v}" ${v===f.operator?'selected':''}>${l}</option>`).join('')}</select><input aria-label="필터 ${index+1} 값" data-index="${index}" data-part="value" value="${esc(f.value)}" list="values-${index}" placeholder="값 선택 / 입력" ${['null','notnull'].includes(f.operator)?'disabled':''}></div>${f.operator==='between'?`<div class="between"><span class="hint">위 값부터 →</span><input aria-label="필터 ${index+1} 끝값" data-index="${index}" data-part="value2" value="${esc(f.value2||'')}" placeholder="끝값"></div>`:''}<datalist id="values-${index}">${values.map(v=>`<option value="${esc(v)}">`).join('')}</datalist></div>`}).join('');$('filterRows').querySelectorAll('[data-part]').forEach(el=>{el.addEventListener(el.tagName==='SELECT'?'change':'input',()=>{const f=filters[Number(el.dataset.index)];f[el.dataset.part]=el.value;if(el.dataset.part==='column'){f.value='';f.value2=''}if(['column','operator'].includes(el.dataset.part))renderFilters();markDirty()})});$('filterRows').querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{filters.splice(Number(btn.dataset.remove),1);renderFilters();markDirty()})}
function addFilter(){if(filters.length>=12){toast('직접 조건은 최대 12개까지 추가할 수 있어요.');return}const col=columns.find(c=>c.name==='available_quantity')||columns.find(numeric)||columns[0];filters.push({column:col.name,operator:numeric(col)?'gte':'eq',value:'',value2:''});renderFilters();markDirty()}
function metricOptions(){const old=$('metric').value,op=$('aggregate').value;options($('metric'),columns.filter(c=>op==='distinct'?c.type!=='BLOB':numeric(c)).map(c=>c.name));const preferred=['total_quantity','총재고','inventory_retail_value','order_quantity','발주','received_quantity','issue_count'].find(k=>[...$('metric').options].some(o=>o.value===k));if(![...$('metric').options].some(o=>o.value===old)&&preferred)$('metric').value=preferred;$('metric').disabled=['count','weighted'].includes(op)}
function groupChanged(){const mode=$('groupMode').value;$('groupFields').hidden=mode==='detail';if(mode!=='detail'&&mode!=='custom'){const field=Q.findRole(columns,mode);if(!field){toast('현재 SQL에는 해당 집계 칼럼이 없습니다.');$('groupMode').value='detail';$('groupFields').hidden=true}else{$('group1').value=field;$('group2').value=$('group3').value=''}}if(mode==='custom'&&!$('group1').value)$('group1').value=Q.findRole(columns,'category')||columns[0].name;updateSort();markDirty()}
