async function runQuery(scroll=false){if(!db)return;try{$('error').hidden=true;const cfg=getConfig();if(cfg.quick.from&&cfg.quick.to&&cfg.quick.from>cfg.quick.to)throw Error('시작일은 종료일 이전이어야 합니다.');const compiled=Q.compile(cfg,columns);$('run').disabled=true;$('runState').textContent='조회 중';await new Promise(requestAnimationFrame);const start=performance.now();const total=execute('SELECT COUNT(*) AS n FROM ('+compiled.sql+') AS counted',compiled.params).rows[0].n;const data=execute(compiled.sql+'\nLIMIT 50000',compiled.params,50000);result={...data,total,compiled,config:JSON.parse(JSON.stringify(cfg)),elapsed:performance.now()-start};pageOffset=0;$('resultTitle').textContent=$('preset').value==='custom'?sourceLabels[currentSource]||currentSource:Q.presets.find(p=>p.id===$('preset').value)?.label.replace(/^\d+ · /,'')||'조회 결과';$('runState').textContent='조회 완료';$('runState').className='statepill';previewSQL();updateResult();if(scroll&&innerWidth<800)$('resultTitle').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){showError(e)}finally{$('run').disabled=false}}
function updateResult(){const rows=result.rows,names=result.columns;const nums=names.filter(name=>rows.some(r=>typeof r[name]==='number'));const oldX=$('chartX').value,oldY=$('chartY').value;options($('chartX'),names);options($('chartY'),nums);const xDefault=Q.findRole(names.map(name=>({name})),'category')||Q.findRole(names.map(name=>({name})),'date')||Q.findRole(names.map(name=>({name})),'name')||names.find(k=>!nums.includes(k))||names[0];const yDefault=['metric_value','inventory_retail_value','total_quantity','stockout_hours','issue_count','received_quantity'].find(k=>nums.includes(k))||nums[0];$('chartX').value=names.includes(oldX)?oldX:xDefault||'';$('chartY').value=nums.includes(oldY)?oldY:yDefault||'';if(/pct|ratio|품절율/.test($('chartY').value)||$('chartY').value==='metric_value'&&getConfig().metric.operation==='weighted')$('chartAggregate').value='avg';else $('chartAggregate').value='sum';if(!nums.length)$('chartType').value='none';else if($('chartType').value==='none')$('chartType').value='bar';$('statRows').textContent=num(result.total);$('statRowsSub').textContent=result.total>50000?'최대 50,000행 표시/내보내기':'필터·집계 적용 후';$('statTime').textContent=num(result.elapsed,1)+' ms';$('tableCount').textContent=num(result.total)+'행 / '+names.length+'칼럼';const id=Q.findRole(names.map(name=>({name})),'id'),cat=Q.findRole(names.map(name=>({name})),'category');const distinct=id||cat||names[0];$('statDistinctLabel').textContent=id?'고유 상품':distinct?label(distinct)+' · 고유값':'고유값';$('statDistinct').textContent=distinct?num(new Set(rows.map(r=>r[distinct]).filter(x=>x!==null)).size):'—';$('statDistinctSub').textContent='조회된 '+num(rows.length)+'개 결과행 기준';const stockLike=names.some(k=>/inventory|재고|quantity|available/i.test(k));const d=Q.findRole(names.map(name=>({name})),'date');const multipleDays=d&&new Set(rows.map(r=>r[d])).size>1;let warnings=[];if(stockLike&&(multipleDays||result.config.groups.length&&!result.config.groups.includes(Q.findRole(columns,'date'))))warnings.push('여러 날 재고를 합산한 값은 특정일의 보유재고액이 아닙니다. 일별 집계 또는 날짜 필터를 확인하세요.');if(result.total>50000)warnings.push('결과가 50,000행을 초과해 상위 50,000행만 표시·내보냅니다. 조건을 좁혀 주세요.');$('semanticWarning').textContent=warnings.join(' ');$('semanticWarning').hidden=!warnings.length;renderTable();renderChart()}
function cell(value){if(value===null)return '<span class="null">—</span>';if(value instanceof Uint8Array)return '<span class="muted">BLOB · '+num(value.length)+' bytes</span>';if(typeof value==='number')return num(value,Number.isInteger(value)?0:2);return esc(value)}
function renderTable(){const size=Number($('pageSize').value),rows=result.rows.slice(pageOffset,pageOffset+size);$('table').innerHTML='<table><thead><tr>'+result.columns.map(c=>`<th><button data-sort="${esc(c)}" title="${esc(c)}">${esc(label(c))} ${result.config?.sort===c?(result.config.direction==='ASC'?'↑':'↓'):'↕'}</button></th>`).join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+result.columns.map(c=>`<td class="${typeof row[c]==='number'?'number':''}" title="${esc(row[c] instanceof Uint8Array?'BLOB '+row[c].length+' bytes':String(row[c]??'NULL').slice(0,1000))}">${cell(row[c])}</td>`).join('')+'</tr>').join('')+(rows.length?'':`<tr><td colspan="${Math.max(1,result.columns.length)}" style="text-align:center;padding:55px;color:#97a48d">조건에 맞는 결과가 없습니다. 필터를 조정해 다시 조회하세요.</td></tr>` )+'</tbody></table>';$('table').querySelectorAll('[data-sort]').forEach(btn=>btn.onclick=()=>{const col=btn.dataset.sort;if($('sort').value===col)$('direction').value=$('direction').value==='DESC'?'ASC':'DESC';else{$('sort').value=col;$('direction').value='DESC'}runQuery()});$('pageInfo').textContent=result.rows.length?`${num(pageOffset+1)}–${num(Math.min(pageOffset+size,result.rows.length))} / ${num(result.rows.length)}행`:'조회 결과 0행';$('pageNumber').textContent=(result.rows.length?Math.floor(pageOffset/size)+1:0)+' / '+Math.ceil(result.rows.length/size);$('prev').disabled=pageOffset===0;$('next').disabled=pageOffset+size>=result.rows.length}
function renderChart(){const type=$('chartType').value,x=$('chartX').value,y=$('chartY').value,rows=result.rows;const numbers=rows.filter(r=>typeof r[y]==='number'&&Number.isFinite(r[y]));const total=numbers.reduce((s,r)=>s+r[y],0),rateLike=/pct|ratio|품절율/.test(y)||(y==='metric_value'&&result.config?.metric.operation==='weighted');$('statMetricLabel').textContent=y?label(y)+(rateLike?' · 범위':' · 합계'):'숫자 지표';$('statMetric').textContent=numbers.length?(rateLike?num(Math.min(...numbers.map(r=>r[y])),1)+'~'+num(Math.max(...numbers.map(r=>r[y])),1):money(total)):'—';$('statMetricSub').textContent=rateLike?'비율은 합산하지 않고 최솟값~최댓값 표시':'조회된 결과행 단순 합계 · 단위 확인';if(type==='none'||!x||!y||!numbers.length){$('chart').innerHTML='<div class="chartempty">숫자 칼럼과 차트 형식을 선택하면 시각화가 나타납니다.</div>';return}const width=780,height=238,pad=47;let svg='';if(type==='scatter'){const pts=numbers.filter(r=>typeof r[x]==='number'&&Number.isFinite(r[x])).slice(0,1200);if(!pts.length){$('chart').innerHTML='<div class="chartempty">산점도는 X와 Y 모두 숫자 칼럼이 필요합니다.</div>';return}const xs=pts.map(r=>r[x]),ys=pts.map(r=>r[y]),minx=Math.min(0,...xs),maxx=Math.max(1,...xs),miny=Math.min(0,...ys),maxy=Math.max(1,...ys);svg+=`<line x1="${pad}" y1="${height-30}" x2="${width-10}" y2="${height-30}" stroke="#d9e4d4"/>`;for(const r of pts){const px=pad+(r[x]-minx)/(maxx-minx||1)*(width-pad-25),py=height-30-(r[y]-miny)/(maxy-miny||1)*(height-50);svg+=`<circle cx="${px}" cy="${py}" r="4" fill="#4f9d7d" opacity=".6"><title>${esc(label(x))}: ${num(r[x],2)} / ${esc(label(y))}: ${num(r[y],2)}</title></circle>`}svg+=`<text x="${pad}" y="${height-9}">${num(minx)}</text><text x="${width-15}" y="${height-9}" text-anchor="end">${num(maxx)}</text>`;$('chartNote').textContent=label(x)+' × '+label(y)+' · 최대 1,200개 점'}else{const grouped=new Map();for(const r of numbers){const key=r[x]===null?'NULL':String(r[x]);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(r[y])}const agg=$('chartAggregate').value;let pts=[...grouped].map(([k,vs])=>[k,agg==='count'?vs.length:agg==='avg'?vs.reduce((a,b)=>a+b,0)/vs.length:agg==='max'?Math.max(...vs):agg==='min'?Math.min(...vs):vs.reduce((a,b)=>a+b,0)]);if(type==='line')pts.sort((a,b)=>a[0].localeCompare(b[0],'ko',{numeric:true}));else pts.sort((a,b)=>b[1]-a[1]);pts=pts.slice(0,type==='line'?60:10);const max=Math.max(1,...pts.map(p=>p[1])),min=Math.min(0,...pts.map(p=>p[1])),plot=height-52,ys=v=>height-31-(v-min)/(max-min||1)*plot;for(let i=0;i<4;i++){const v=min+(max-min)*i/3,py=ys(v);svg+=`<line x1="${pad}" x2="${width-12}" y1="${py}" y2="${py}" stroke="#edf1e6"/><text x="${pad-7}" y="${py+3}" text-anchor="end">${money(v)}</text>`}if(type==='bar'){const step=(width-pad-14)/pts.length;for(const [i,p]of pts.entries()){const xx=pad+i*step+step*.22,zero=ys(0),yy=ys(p[1]);svg+=`<rect x="${xx}" y="${Math.min(yy,zero)}" width="${step*.56}" height="${Math.max(1,Math.abs(zero-yy))}" rx="3" fill="${i===0?'#277d60':'#93bda3'}"><title>${esc(p[0])}: ${num(p[1],2)}</title></rect><text x="${xx+step*.28}" y="${height-8}" text-anchor="middle">${esc(p[0].length>8?p[0].slice(0,7)+'…':p[0])}</text>`}}else{const px=i=>pad+(width-pad-20)*(pts.length===1?.5:i/(pts.length-1));svg+=`<polyline points="${pts.map((p,i)=>px(i)+','+ys(p[1])).join(' ')}" fill="none" stroke="#297e62" stroke-width="2.5"/>`;for(const [i,p]of pts.entries()){svg+=`<circle cx="${px(i)}" cy="${ys(p[1])}" r="2.5" fill="#297e62"><title>${esc(p[0])}: ${num(p[1],2)}</title></circle>`;if(i===0||i===pts.length-1||i===Math.floor(pts.length/2))svg+=`<text x="${px(i)}" y="${height-8}" text-anchor="middle">${esc(p[0].length>10?p[0].slice(5,10):p[0])}</text>`}}$('chartNote').textContent=label(x)+'별 '+label(y)+' '+({sum:'합계',avg:'단순평균',min:'최소',max:'최대',count:'행 수'}[agg])+(rateLike?' · 비율은 가중 집계 아님':'')+' · '+(type==='bar'?'상위 10개':'최대 60개 구간')+' · 결과행 집계'}$('chart').innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(label(x)+'별 '+label(y))}">${svg}</svg>`}
function download(content,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){if(!result.columns.length)return;const f=v=>{if(v instanceof Uint8Array)v='BLOB '+v.length+' bytes';if(typeof v==='string'&&/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+String(v??'').replace(/"/g,'""')+'"'};download('\ufeff'+[result.columns.map(f).join(','),...result.rows.map(r=>result.columns.map(c=>f(r[c])).join(','))].join('\r\n'),'SCM_조회결과_'+new Date().toISOString().slice(0,10)+'.csv','text/csv;charset=utf-8');toast(num(result.rows.length)+'행을 CSV로 내려받았습니다.')}
function columnDialog(){draftColumns=[...selected];$('columnSearch').value='';drawColumnOptions();$('columnDialog').showModal()}
function drawColumnOptions(){const search=$('columnSearch').value.toLowerCase();$('columnOptions').innerHTML=columns.filter(c=>(c.name+' '+label(c.name)).toLowerCase().includes(search)).map(c=>`<label class="columnoption"><input type="checkbox" value="${esc(c.name)}" ${draftColumns.includes(c.name)?'checked':''}><span>${esc(label(c.name))}<small>${esc(c.name)}</small></span><em>${esc(c.type)}</em></label>`).join('');$('columnOptions').querySelectorAll('input').forEach(input=>input.onchange=()=>{if(input.checked){if(!draftColumns.includes(input.value))draftColumns.push(input.value)}else draftColumns=draftColumns.filter(c=>c!==input.value)})}
function profiles(){try{const p=JSON.parse(localStorage.getItem(STORE)||'[]');return Array.isArray(p)?p:[]}catch(e){return []}}
function saveProfiles(p){try{localStorage.setItem(STORE,JSON.stringify(p));$('savedCount').textContent=p.length}catch(e){toast('브라우저에서 저장할 수 없습니다. 조회 설정을 JSON으로 내보내 주세요.')}}
function saveCurrent(){const name=$('profileName').value.trim();if(!name){$('profileName').focus();return}const list=profiles();if(list.length>=20){toast('저장한 조회가 20개입니다. 사용하지 않는 조회를 삭제해 주세요.');return}list.unshift({id:Date.now().toString(36),name,saved:new Date().toISOString(),preset:$('preset').value,source:currentSource,config:getConfig(),period:$('period').value,groupMode:$('groupMode').value,chart:{type:$('chartType').value,x:$('chartX').value,y:$('chartY').value}});saveProfiles(list);$('saveDialog').close();toast('조회 조건을 저장했습니다.');renderSaved()}
function renderSaved(){const list=profiles();$('savedCount').textContent=list.length;$('savedList').innerHTML=list.map(p=>`<article class="panel savedcard"><span class="eyebrow">SAVED QUERY / ${esc(p.saved.slice(0,10))}</span><h2 class="savedtitle">${esc(p.name)}</h2><p>${esc(Q.presets.find(x=>x.id===p.preset)?.label||sourceLabels[p.source]||p.source)}<br>${esc(p.config.quick.from||'전체')} — ${esc(p.config.quick.to||'전체')}<br>직접 조건 ${p.config.filters.length}개 · ${p.config.groups.length?'집계 조회':'상세 조회'}</p><div class="actions"><button class="primary" data-load="${p.id}">불러오기 →</button><button data-delete="${p.id}">삭제</button></div></article>`).join('')||'<div class="savedempty">아직 저장한 조회가 없습니다.<br>조회 화면에서 ☆ 저장을 눌러 보세요.</div>';$('savedList').querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>applyProfile(list.find(p=>p.id===b.dataset.load)));$('savedList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{saveProfiles(profiles().filter(p=>p.id!==b.dataset.delete));renderSaved()})}
function applyProfile(p){try{changeSource(p.preset==='custom'?{source:p.source,run:false}:{presetId:p.preset,run:false});const c=p.config;if(c.selected.some(x=>!columns.some(v=>v.name===x)))throw Error('현재 DB의 칼럼이 저장한 조회와 다릅니다.');selected=[...c.selected];filters=c.filters.map(x=>({...x}));$('period').value=p.period||'custom';$('dateFrom').value=c.quick.from;$('dateTo').value=c.quick.to;for(const role of ['category','md','supplier']){const value=c.quick[role]||'';if(value&&![...$(role).options].some(o=>o.value===value))$(role).insertAdjacentHTML('beforeend',`<option value="${esc(value)}">${esc(value)}</option>`);$(role).value=value}$('search').value=c.quick.search||'';$('logic').value=c.logic;$('groupMode').value=p.groupMode||'detail';$('groupFields').hidden=!c.groups.length;['group1','group2','group3'].forEach((id,i)=>$(id).value=c.groups[i]||'');$('aggregate').value=c.metric.operation;metricOptions();$('metric').value=c.metric.column;$('columnCount').textContent=selected.length;updateSort();$('sort').value=c.sort;$('direction').value=c.direction;renderFilters();showPage('workspace');runQuery().then(()=>{$('chartType').value=p.chart.type;$('chartX').value=p.chart.x;$('chartY').value=p.chart.y;renderChart()});toast('저장한 조회를 불러왔습니다.')}catch(e){showError(e);showPage('workspace')}}
function showPage(page){appPage=page;for(const id of ['workspace','saved','schema','help'])$(id).hidden=id!==page;document.querySelectorAll('.navitem').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const titles={workspace:['조회 만들기','원하는 조건으로, 바로 조회.','SQL을 선택하고 필터를 조합하세요. 실행되는 SQL도 함께 확인할 수 있습니다.'],saved:['저장한 조회','다시 쓸 조건은 저장해 두세요.','조회 설정과 연결 DB는 이 브라우저에 보관합니다.'],schema:['데이터베이스 구조','어떤 데이터가 있는지 살펴보세요.','업무 테이블, 분석용 뷰, 원본 칼럼과 자료형을 확인합니다.'],help:['사용 가이드','처음이라면 여기부터.','필터와 집계의 적용 순서, DB 파일 열기와 결과 해석 안내입니다.']};[$('pageCrumb').textContent,$('pageTitle').textContent,$('pageIntro').textContent]=titles[page];if(page==='saved')renderSaved();if(page==='schema')renderSchema();window.scrollTo(0,0)}
function renderSchema(){if(!db)return;const name=$('schemaSource').value||currentSource;if(!objects.some(o=>o.name===name))return;const fields=execute('PRAGMA table_info('+Q.quote(name)+')').rows;const count=execute('SELECT COUNT(*) AS n FROM '+Q.quote(name)).rows[0].n;let dict=[];try{dict=execute('SELECT * FROM column_dictionary WHERE table_name=?',[name]).rows}catch(e){}const obj=objects.find(o=>o.name===name);$('schemaContent').innerHTML=`<div class="schema-summary"><article class="panel">데이터 소스<strong>${esc(obj.type==='view'?'분석 뷰':'테이블')}</strong></article><article class="panel">현재 행 수<strong>${num(count)}</strong></article><article class="panel">전체 칼럼<strong>${fields.length}</strong></article></div><section class="panel"><div class="panelheading"><h2>${esc(sourceLabels[name]||name)} <span class="muted">${esc(name)}</span></h2><button id="queryThisSource" class="linkbutton">이 데이터 조회 →</button></div><div class="table-scroll"><table><thead><tr><th>칼럼</th><th>DB 이름</th><th>자료형</th><th>원본 순서</th><th>기본키</th></tr></thead><tbody>${fields.map(f=>{const d=dict.find(x=>x.database_column===f.name);return `<tr><td>${esc(d?.original_name||label(f.name))}</td><td>${esc(f.name)}</td><td>${esc(f.type||'계산식')}</td><td>${d?.ordinal??'—'}</td><td>${f.pk?'KEY '+f.pk:'—'}</td></tr>`}).join('')}</tbody></table></div>${obj.type==='view'?`<details class="sqlpanel"><summary>분석 뷰 정의 보기 ⌄</summary><pre>${esc(obj.sql)}</pre></details>`:''}</section>`;$('queryThisSource').onclick=()=>{changeSource({source:name});showPage('workspace')}}
async function loadDatabase(file=null,forceDefault=false){hubLoading=true;const serial=++loadSerial;const hadDB=!!db;$('loading').hidden=false;$('loadingText').textContent=file?'내 DB를 브라우저에서 여는 중입니다.':'가상 SQLite DB를 불러오는 중입니다.';for(const id of ['openDb','mobileOpenDb','refreshDb','resetDb'])$(id).disabled=true;try{if(!enginePromise)enginePromise=initSqlJs({locateFile:name=>'assets/'+name});const startRecord=await SCMHub.get();let shared=forceDefault?null:startRecord;let bytes;if(file){if(file.size>100*1024*1024)throw Error('현재 화면은 100MB 이하의 SCM DB를 지원합니다.');bytes=new Uint8Array(await file.arrayBuffer())}else if(shared){bytes=shared.bytes}else{const runtime=await fetch('runtime.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('사이트 설정을 읽을 수 없습니다.');return r.json()});const response=await fetch(runtime.databaseUrl,{cache:'no-store'});if(!response.ok)throw Error('가상 DB를 불러올 수 없습니다.');if(!('DecompressionStream'in window))throw Error('압축 DB를 열려면 최신 Chrome 또는 Edge를 사용하세요. 내 DB 열기는 사용할 수 있습니다.');$('loadingText').textContent='데이터베이스 압축을 해제하는 중입니다.';const stream=response.body.pipeThrough(new DecompressionStream('gzip'));bytes=new Uint8Array(await new Response(stream).arrayBuffer())}const SQL=await enginePromise;if(serial!==loadSerial)return;$('loadingText').textContent='테이블과 분석 SQL을 준비하는 중입니다.';await new Promise(requestAnimationFrame);const candidate=new SQL.Database(bytes);try{SCMHub.check(candidate);candidate.exec('PRAGMA query_only=ON');candidate.exec('SELECT * FROM v_sku_day LIMIT 0')}catch(e){candidate.close();throw e}if(file||forceDefault){shared=await SCMHub.save(bytes,{name:file?file.name:'동봉 가상 SCM DB',source:file?'db':'synthetic',synthetic:!file},startRecord?.revision||null)}syncRevision=shared?.revision||null;if(db)db.close();db=candidate;loadedName=shared?.meta.name|| (file?file.name:'scm.db · 가상 스냅샷');objects=execute("SELECT type,name,sql FROM sqlite_master WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%' ORDER BY type,name").rows;const counts=execute('SELECT COUNT(*) AS n FROM dim_product').rows[0].n;const datesCount=execute('SELECT COUNT(*) AS n FROM dim_date').rows[0].n;$('dbName').textContent=loadedName;$('mobileDbName').textContent=loadedName;$('dbMeta').textContent=num(counts)+'개 상품 · '+datesCount+'일 · '+objects.filter(o=>o.type==='table').length+'개 테이블';$('dbStatus').textContent=shared?'센터와 같은 DB · 연결됨':'가상 DB · 데이터 연결 전';const groups=[['업무 테이블',objects.filter(o=>o.type==='table'&&o.name.endsWith('_daily'))],['분석용 SQL 뷰',objects.filter(o=>o.type==='view')],['보관·관리 테이블',objects.filter(o=>o.type==='table'&&!o.name.endsWith('_daily'))]];$('source').innerHTML=groups.map(([title,rs])=>`<optgroup label="${title}">${rs.map(o=>`<option value="${esc(o.name)}">${esc(sourceLabels[o.name]||o.name)} · ${esc(o.name)}</option>`).join('')}</optgroup>`).join('');$('schemaSource').innerHTML=$('source').innerHTML;$('preset').innerHTML=Q.presets.map(p=>`<option value="${p.id}">${p.label}</option>`).join('')+'<option value="custom">직접 테이블/뷰 선택</option>';$('loading').hidden=true;showPage('workspace');changeSource({presetId:'integrated'});renderSaved();toast(shared?'연결 DB를 열었습니다. 센터와 같은 데이터를 읽습니다.':'가상 DB가 준비되었습니다. 데이터 연결에서 센터에도 반영할 수 있습니다.')}catch(e){$('loading').hidden=true;if(hadDB){toast(e.message);showError(e)}else{$('loading').hidden=false;$('loadingText').textContent='DB 연결을 확인해 주세요: '+e.message;if(!$('retryLoad')){$('loading').insertAdjacentHTML('beforeend','<button id="retryLoad">다시 시도</button>');$('retryLoad').onclick=()=>{$('retryLoad').remove();loadDatabase()}}}enginePromise=null;console.error(e)}finally{for(const id of ['openDb','mobileOpenDb','refreshDb','resetDb'])$(id).disabled=false;hubLoading=false;if(pendingRevision&&pendingRevision!==syncRevision){pendingRevision=null;loadDatabase()}else pendingRevision=null}}
