$('preset').onchange=()=>changeSource($('preset').value==='custom'?{source:$('source').value}:{presetId:$('preset').value});$('source').onchange=()=>changeSource({source:$('source').value});
$('period').onchange=()=>{setPeriod();quickOptions();markDirty()};for(const id of ['dateFrom','dateTo'])$(id).onchange=()=>{$('period').value='custom';quickOptions();markDirty()};for(const id of ['category','md','supplier'])$(id).onchange=()=>{quickOptions();markDirty()};$('search').oninput=markDirty;$('logic').onchange=markDirty;
$('clearFilters').onclick=()=>{$('category').value=$('md').value=$('supplier').value=$('search').value='';$('period').value='latest';filters=[];setPeriod();quickOptions();renderFilters();markDirty()};$('addFilter').onclick=addFilter;$('groupMode').onchange=groupChanged;for(const id of ['group1','group2','group3','aggregate','metric'])$(id).onchange=()=>{metricOptions();updateSort();markDirty()};$('sort').onchange=$('direction').onchange=markDirty;$('run').onclick=()=>runQuery(true);$('export').onclick=exportCSV;$('pageSize').onchange=()=>{pageOffset=0;renderTable()};$('prev').onclick=()=>{pageOffset=Math.max(0,pageOffset-Number($('pageSize').value));renderTable()};$('next').onclick=()=>{pageOffset+=Number($('pageSize').value);renderTable()};for(const id of ['chartType','chartX','chartY','chartAggregate'])$(id).onchange=renderChart;
$('chooseColumns').onclick=columnDialog;$('closeColumns').onclick=()=>$('columnDialog').close();$('columnSearch').oninput=drawColumnOptions;$('allColumns').onclick=()=>{draftColumns=columns.map(c=>c.name);drawColumnOptions()};$('defaultColumns').onclick=()=>{draftColumns=defaultSelected();drawColumnOptions()};$('applyColumns').onclick=()=>{if(!draftColumns.length){toast('한 개 이상의 칼럼을 선택하세요.');return}selected=columns.filter(c=>draftColumns.includes(c.name)).map(c=>c.name);$('columnCount').textContent=selected.length;updateSort();$('columnDialog').close();markDirty()};
$('save').onclick=()=>{$('profileName').value='';$('saveDialog').showModal();$('profileName').focus()};$('closeSave').onclick=()=>$('saveDialog').close();$('confirmSave').onclick=saveCurrent;$('profileName').onkeydown=e=>{if(e.key==='Enter')saveCurrent()};$('exportProfiles').onclick=()=>download(JSON.stringify(profiles(),null,2),'SCM_저장한조회.json','application/json');
$('copySql').onclick=async()=>{try{const c=Q.compile(getConfig(),columns);await navigator.clipboard.writeText(Q.interpolated(c.sql,c.params)+';');toast('조건값이 포함된 SQL을 복사했습니다.')}catch(e){toast('SQL 코드를 직접 선택해 복사하세요.')}};
$('mobileOpenDb').onclick=$('openDb').onclick=()=>$('dbFile').click();$('dbFile').onchange=()=>{const f=$('dbFile').files[0];if(f)loadDatabase(f);$('dbFile').value=''};$('resetDb').onclick=()=>loadDatabase(null,true);$('refreshDb').onclick=()=>loadDatabase();document.querySelectorAll('.navitem').forEach(b=>b.onclick=()=>{if(db)showPage(b.dataset.page)});$('schemaSource').onchange=renderSchema;$('schemaQuick').onclick=()=>{$('schemaSource').value=currentSource;showPage('schema')};
window.Workbench={getConfig,runQuery,execute,changeSource,loadDatabase,inspectState:()=>({loadedName,currentSource,columns,selected,filters,result,dates})};
SCMHub.subscribe(record=>{if(hubLoading){pendingRevision=record.revision;return}if(record.revision!==syncRevision)loadDatabase()});
renderSaved();loadDatabase();
